sqlMap.insert:
INSERT INTO PA_BEN_BASE (PA_BEN_BASE_SEQ, PERSON_ID, SOCIAL_NO, AVG_SALARY, PAY_SALARY, SOCIAL_STATUS, IMP_TYPE, CREATE_DATE, CREATED_BY, ACTIVITY) (SELECT PA_BEN_BASE_SEQ.NEXTVAL, T.PERSON_ID, T.SOCIAL_NO, T.AVG_SALARY, T.AVG_SALARY, T.SOCIAL_STATUS, 'N', SYSDATE, #adminID#, 1 FROM PA_BEN_MANAGE T,HR_EMPLOYEE E WHERE TO_CHAR(T.CREATE_DATE, 'yyyymm') = #pabDate# AND T.PERSON_ID = E.PERSON_ID AND T.PERSON_ID NOT IN(SELECT T.PERSON_ID FROM PA_BEN_BASE B)
(E.DATE_LEFT IS NULL OR (E.DATE_LEFT IS NOT NULL AND E.DATE_LEFT >= TO_DATE(#leftDate:DATE#,'YYYY-MM-DD')))
)
